// Internal pool planner only. No grant, pickup, inventory or service routing hook.
class Offline70TowerDropPlannerFG175 {
 internal static int[] Pool(int type,int code){switch(type*1000000+code){case 5000500:return new int[]{};case 5000501:return new int[]{};case 5000600:return new int[]{};case 5000601:return new int[]{6521,10000};case 5000602:return new int[]{6524,10000};case 5000603:return new int[]{};case 5000604:return new int[]{};case 5000605:return new int[]{6515,10000,6521,10000};case 5000606:return new int[]{6515,10000,6524,10000};case 5005003:return new int[]{};case 5005004:return new int[]{6521,5000};case 5005301:return new int[]{};case 5005302:return new int[]{};case 5005303:return new int[]{6520,10000};case 5005304:return new int[]{6519,10000};case 5005305:return new int[]{6523,10000};case 5005306:return new int[]{};case 5005307:return new int[]{};case 5005308:return new int[]{};case 5005309:return new int[]{6520,10000};case 5005312:return new int[]{};case 5005313:return new int[]{};case 5005600:return new int[]{6520,10000};case 5010201:return new int[]{6521,10000};case 5010202:return new int[]{6520,10000};case 5010203:return new int[]{};case 5010301:return new int[]{};case 5010304:return new int[]{};case 5010401:return new int[]{};case 5010402:return new int[]{6515,10000,6518,10000};case 5010504:return new int[]{6520,10000};case 5015201:return new int[]{6518,10000};case 5015202:return new int[]{6523,10000};case 5015203:return new int[]{6515,10000};case 5015204:return new int[]{6524,10000};case 5015205:return new int[]{6523,10000};case 5015206:return new int[]{};case 5015207:return new int[]{};case 5015501:return new int[]{};case 5015502:return new int[]{};case 5015801:return new int[]{};case 5015901:return new int[]{};case 5020002:return new int[]{6524,5000};case 5020201:return new int[]{};case 5020401:return new int[]{6523,10000};case 5020402:return new int[]{6515,10000,6519,10000};case 5020403:return new int[]{};case 5020500:return new int[]{};case 5020501:return new int[]{6523,10000};case 5020600:return new int[]{6515,10000,6519,10000};case 5020601:return new int[]{6520,10000};case 5020603:return new int[]{};case 50501:return new int[]{};case 50502:return new int[]{6515,10000,6518,10000};case 50503:return new int[]{};case 50504:return new int[]{6515,2000};case 50505:return new int[]{6519,10000};case 50506:return new int[]{};case 50507:return new int[]{6515,10000,6518,10000};case 50508:return new int[]{6515,2000};case 50509:return new int[]{6515,10000};case 55001:return new int[]{};case 55002:return new int[]{};case 55003:return new int[]{};case 55004:return new int[]{};case 55005:return new int[]{6515,2000};case 55006:return new int[]{};case 55007:return new int[]{6519,10000};case 55008:return new int[]{};case 55009:return new int[]{};case 55010:return new int[]{};case 55011:return new int[]{};case 55012:return new int[]{6515,10000};case 55013:return new int[]{};case 55014:return new int[]{};case 55015:return new int[]{};case 55016:return new int[]{6515,10000};case 55017:return new int[]{};case 55018:return new int[]{};case 55019:return new int[]{};case 55020:return new int[]{};case 55021:return new int[]{6515,10000};case 55022:return new int[]{6523,10000};case 55023:return new int[]{6515,10000};case 55024:return new int[]{6518,10000};case 55025:return new int[]{}; default:throw new InvalidDataException("Unverified tower enemy drop pool");}}
 internal static int[] Plan(int type,int code,bool enabled,Func<int,int> random){if(type!=0&&type!=5)throw new InvalidDataException("Tower enemy type");int[] pool=Pool(type,code);List<int> items=new List<int>();if(!enabled)return items.ToArray();if(random==null)throw new InvalidDataException("Tower random source");
 if(type==5){for(int i=0;i<pool.Length;i+=2){int roll=random(10000);if(roll<0||roll>=10000)throw new InvalidDataException("Tower roll");if(roll<pool[i+1])items.Add(pool[i]);}}
 else {int roll=random(10000);if(roll<0||roll>=10000)throw new InvalidDataException("Tower roll");int sum=0;for(int i=0;i<pool.Length;i+=2){sum=checked(sum+pool[i+1]);if(roll<sum){items.Add(pool[i]);break;}}}return items.ToArray();}
